-- Açıklama   : Satın alma/mal kabul kaynak zinciri ve sürümlü set değişiklikleri.
CREATE TABLE purchase_orders(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,supplier_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,currency CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'ordered',reference TEXT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(supplier_id) REFERENCES suppliers(id),CHECK(currency IN('TRY','EUR','USD','GBP')),CHECK(status IN('ordered','partially_received','received','cancelled'))) ENGINE=InnoDB;
CREATE TABLE purchase_items(purchase_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,variant_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,quantity INT NOT NULL,received INT NOT NULL DEFAULT 0,unit_cost_minor BIGINT NOT NULL,PRIMARY KEY(purchase_id,variant_id),FOREIGN KEY(purchase_id) REFERENCES purchase_orders(id),FOREIGN KEY(variant_id) REFERENCES variants(id),CHECK(quantity>0 AND received BETWEEN 0 AND quantity AND unit_cost_minor>=0)) ENGINE=InnoDB;
CREATE TABLE purchase_receipts(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,purchase_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,reference TEXT NOT NULL,actor_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(purchase_id) REFERENCES purchase_orders(id)) ENGINE=InnoDB;
CREATE TABLE purchase_receipt_items(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,receipt_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,variant_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,lot_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,quantity INT NOT NULL,quarantined BOOLEAN NOT NULL,movement_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,FOREIGN KEY(receipt_id) REFERENCES purchase_receipts(id),FOREIGN KEY(variant_id) REFERENCES variants(id),FOREIGN KEY(lot_id) REFERENCES inventory_lots(id),FOREIGN KEY(movement_id) REFERENCES inventory_movements(id),CHECK(quantity>0 AND quarantined IN(0,1))) ENGINE=InnoDB;
CREATE TABLE bundle_changes(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,variant_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,version INT NOT NULL,old_components JSON NOT NULL,new_components JSON NOT NULL,reason TEXT NOT NULL,actor_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(variant_id,version),FOREIGN KEY(variant_id) REFERENCES variants(id),CHECK(version>0)) ENGINE=InnoDB;
